auto func (auto value){  
    int count = 0;  
    for (int i = 0; i < value.size(); i++) {  
        count += value[i];  
    }  
    return count;  
}

auto func (auto value){  
    int count = 0;  
    for (char c : value) {  
        if (isupper(c)) {  
            count++;  
        }  
    }  
    return count;  
}
